-- Anonymous page-view counters for the admin analytics page: one row per day, path and
-- referring site, with a count. No user id, IP address or cookie is stored.
CREATE TABLE IF NOT EXISTS "kvelpo_pageview_daily" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "kvelpo_pageview_daily_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"day" date NOT NULL,
	"path" varchar(256) NOT NULL,
	"referrer" varchar(128) DEFAULT '' NOT NULL,
	"views" integer DEFAULT 0 NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "pageview_daily_unique_idx" ON "kvelpo_pageview_daily" ("day", "path", "referrer");
CREATE INDEX IF NOT EXISTS "pageview_daily_day_idx" ON "kvelpo_pageview_daily" ("day");
